with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , INSURCO_CLAIM_NO as LEADER_CLAIM_REFERENCE
        , 'BJAZ_HM_COINSU_CLM_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_coinsu_clm_dtls') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LEADER_CLAIM_REFERENCE end) as LEADER_CLAIM_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when LEADER_CLAIM_REFERENCE is not null
                     then md5(upper(coalesce(cast(LEADER_CLAIM_REFERENCE as varchar), '')))
                end as SAT_CLAIM_CO_RI_SHARE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_CO_RI_SHARE_HASHDIFF is not null
